UPDATE account
SET group_baseline_state = 2,
    updated_at = #{now}
WHERE id = #{accountId}
  AND deleted_at IS NULL
  AND group_baseline_state = 1

mapper.select:
SELECT group_link_id FROM group_link_preview WHERE group_link_id IN
#{groupLinkId}
ORDER BY group_link_id ASC

SELECT group_jid FROM account_group_membership WHERE account_id = #{accountId} AND deleted_at IS NULL AND group_jid IN
#{groupJid}
ORDER BY group_jid ASC

SELECT a.id AS accountId, a.protocol_id AS protocolId, a.protocol_account_id AS protocolAccountId, a.ws_phone AS wsPhone, TRUE AS groupAdmin FROM group_link group_handle INNER JOIN account a ON a.tenant_id = group_handle.tenant_id AND a.deleted_at IS NULL AND a.protocol_account_id IS NOT NULL AND a.protocol_account_id != '' AND a.ws_phone IS NOT NULL AND a.ws_phone != '' INNER JOIN account_state s ON s.tenant_id = a.tenant_id AND s.account_id = a.id AND s.login_state = #{onlineLoginState} AND s.account_state = #{normalAccountState} LEFT JOIN wa_account_group_binding binding ON binding.tenant_id = group_handle.tenant_id AND binding.group_id = group_handle.group_id AND binding.account_id = a.id LEFT JOIN wa_group_participant self_participant ON self_participant.tenant_id = binding.tenant_id AND self_participant.group_id = binding.group_id AND self_participant.id = binding.participant_id AND self_participant.presence_status = 1 WHERE group_handle.id = #{groupLinkId} AND group_handle.deleted_at IS NULL AND a.ws_phone IN
#{phone}
ORDER BY COALESCE( CASE WHEN self_participant.id IS NOT NULL THEN binding.last_observed_at END, 0 ) DESC, a.id ASC LIMIT #{limit}

SELECT id
FROM account_group_membership
WHERE account_id = #{accountId}
  AND deleted_at IS NULL
  AND membership_status NOT IN

    #{preservedStatus}

  AND (
    status_updated_at < #{statusUpdatedAt}
    OR (
      status_updated_at = #{statusUpdatedAt}
      AND status_source NOT IN ('WGP2_ADD', 'WGP2_REMOVE', 'WGP2_LEAVE')
    )
  )

  AND group_jid NOT IN
  #{jid}

ORDER BY id ASC

mapper.update:
UPDATE account_group_membership
SET membership_status = #{row.membershipStatus},
    status_source = #{row.statusSource},
    status_updated_at = #{row.statusUpdatedAt},
    updated_at = #{row.updatedAt}
WHERE id IN
  #{id}
  AND deleted_at IS NULL
  AND membership_status NOT IN

    #{preservedStatus}

  AND (
    status_updated_at < #{row.statusUpdatedAt}
    OR (
      status_updated_at = #{row.statusUpdatedAt}
      AND status_source NOT IN ('WGP2_ADD', 'WGP2_REMOVE', 'WGP2_LEAVE')
    )
  )
ORDER BY id ASC
